        \"direct_impacts\": [\n          {\n            \"critical\": true,\n            \"impact_id\": \"METADATA_TRACE\",\n            \"source_ref\": \"fixture://a14/012/i1\"\n          }\n        ],\n        \"indirect_impacts\": [],\n        \"material_fronts\": [\n          {\n            \"effect_on_scope\": \"PRESERVE\",\n            \"front_id\": \"TRACEABILITY\",\n            \"material\": true,\n            \"scope_ids\": [\n              \"S1\"\n            ],\n            \"source_refs\": [\n              \"fixture://a14/012/f1\"\n            ],\n            \"status\": \"ACCOUNTED\"\n          }\n        ],\n        \"scopes\": [\n          {\n            \"scope_id\": \"S1\",\n            \"scope_kind\": \"GOVERNANCE_SCOPE\",\n            \"source_ref\": \"fixture://a14/012/s1\"\n          }\n        ],\n        \"second_order_impacts\": []\n      },\n      \"handoff\": {\n        \"context_sha256\": \"6666666666666666666666666666666666666666666666666666666666666666\",\n        \"lossy_projection\": false,\n        \"producer_schema_digest_sha256\": \"5555555555555555555555555555555555555555555555555555555555555555\",\n        \"receipt_context_sha256\": \"6666666666666666666666666666666666666666666666666666666666666666\",\n        \"receiver_schema_digest_sha256\": \"5555555555555555555555555555555555555555555555555555555555555555\"\n      },\n      \"signals\": {\n        \"authority_state\": \"SUFFICIENT\",\n        \"currentness_decision\": \"CURRENT\",\n        \"known_cross_scope_impact\": false,\n        \"material_contradiction\": false,\n        \"materiality_level\": \"LOW\",\n        \"required_specialist_count\": 0,\n        \"reversibility_state\": \"DEMONSTRATED\",\n        \"scope_bounded\": \"TRUE\",\n        \"unresolved_material_signal_count\": 0\n      },\n      \"specialist_requirements\": []\n    }\n  ],\n  \"rules\": {\n    \"blocked_scope_ids\": \"Un scope queda bloqueado si: (a) un frente material tiene status BLOCKED, UNRESOLVED, NEED_MORE_EVIDENCE o REQUIRES_DECISION: se bloquean los scope_ids de ese frente; (b) evidence.currentness.decision es STALE_AFFECTED o UNKNOWN_FAIL_CLOSED: se bloquean evidence.currentness.affected_scope_ids; (c) un specialist_requirement con required=true y matched_ref=null: se bloquean sus affected_scope_ids; (d) el handoff no pasa (ver handoff_parity): se bloquean TODOS los scopes; (e) los frentes materiales son inconsistentes (front_id repetido o vacío, scope_ids vacío o fuera de los scopes del caso, status fuera de ACCOUNTED/BLOCKED/UNRESOLVED/NEED_MORE_EVIDENCE/REQUIRES_DECISION, status distinto de ACCOUNTED con effect_on_scope distinto de BLOCKS, o status ACCOUNTED con effect_on_scope distinto de PRESERVE): se bloquean TODOS los scopes. Un frente ACCOUNTED con effect_on_scope PRESERVE no bloquea nada.\",\n    \"critical_impacts\": \"Lista sin repetidos (en orden de aparición) de impact_id de los impactos con critical=true en evidence.direct_impacts, evidence.indirect_impacts y evidence.second_order_impacts.\",\n    \"depth_level\": \"Se calcula solo con el objeto signals del caso, con esta política de precedencia sin pesos: L3 si se cumple cualquiera de L3_if_any; si no, L2 si se cumple cualquiera de L2_if_no_L3_and_any; L1 solo si se cumplen todas las condiciones de L1_requires_all. La profundidad no es permiso de ejecución.\",\n    \"depth_policy\": {\n      \"L1_requires_all\": [\n        \"materiality_level=LOW\",\n        \"scope_bounded=TRUE\",\n        \"authority_state=SUFFICIENT\",\n        \"reversibility_state=DEMONSTRATED\",\n        \"currentness_decision=CURRENT\",\n        \"material_contradiction=false\",\n        \"known_cross_scope_impact=false\",\n        \"unresolved_material_signal_count=0\",\n        \"required_specialist_count=0\"\n      ],\n      \"L2_if_no_L3_and_any\": [\n        \"materiality_level in [MEDIUM,UNKNOWN]\",\n        \"scope_bounded=UNKNOWN\",\n        \"authority_state=UNKNOWN\",\n        \"reversibility_state in [NOT_DEMONSTRATED,UNKNOWN]\",\n        \"currentness_decision in [CURRENT_REBOUND,UNKNOWN_FAIL_CLOSED,UNRESOLVED]\",\n        \"known_cross_scope_impact=UNKNOWN\",\n        \"unresolved_material_signal_count>0\",\n        \"required_specialist_count>0\"\n      ],\n      \"L3_if_any\": [\n        \"materiality_level=HIGH\",\n        \"scope_bounded=FALSE\",\n        \"authority_state=INSUFFICIENT\",\n        \"currentness_decision=STALE_AFFECTED\",\n        \"material_contradiction=true\",\n        \"known_cross_scope_impact=true\"\n      ],\n      \"precedence\": [\n        \"L3_EXPLICIT_HIGH_RISK\",\n        \"L2_MEDIUM_OR_UNPROVEN\",\n        \"L1_FULLY_BOUNDED_LOW_RISK\"\n      ],\n      \"signals\": {\n        \"authority_state\": [\n          \"SUFFICIENT\",\n          \"INSUFFICIENT\",\n          \"UNKNOWN\"\n        ],\n        \"currentness_decision\": [\n          \"CURRENT\",\n          \"CURRENT_REBOUND\",\n          \"STALE_AFFECTED\",\n          \"UNKNOWN_FAIL_CLOSED\",\n          \"UNRESOLVED\"\n        ],\n        \"known_cross_scope_impact\": \"BOOLEAN_OR_UNKNOWN\",\n        \"material_contradiction\": \"BOOLEAN\",\n        \"materiality_level\": [\n          \"LOW\",\n          \"MEDIUM\",\n          \"HIGH\",\n          \"UNKNOWN\"\n        ],\n        \"required_specialist_count\": \"NON_NEGATIVE_INTEGER\",\n        \"reversibility_state\": [\n          \"DEMONSTRATED\",\n          \"NOT_DEMONSTRATED\",\n          \"UNKNOWN\"\n        ],\n        \"scope_bounded\": [\n          \"TRUE\",\n          \"FALSE\",\n          \"UNKNOWN\"\n        ],\n        \"unresolved_material_signal_count\": \"NON_NEGATIVE_INTEGER\"\n      }\n    },\n    \"handoff_parity\": \"PASS solo si los cuatro digests (producer_schema_digest_sha256, receiver_schema_digest_sha256, context_sha256, receipt_context_sha256) son cadenas de 64 caracteres hexadecimales en minúscula, producer_schema_digest_sha256 es igual a receiver_schema_digest_sha256, context_sha256 es igual a receipt_context_sha256 y lossy_projection es false. En cualquier otro caso BLOCK.\",\n    \"lossy_projection_detected\": \"true si handoff.lossy_projection es true; si no, false.\",\n    \"material_fronts\": \"Lista sin repetidos de front_id de evidence.material_fronts con material=true.\",\n    \"missing_required_specialists\": \"Lista de specialist_type de los requirements con required=true y matched_ref=null.\",\n    \"ready_scope_ids\": \"Todos los scope_id del caso que no están bloqueados.\",\n    \"specialist_refs\": \"Lista de matched_ref no nulos de los specialist_requirements.\",\n    \"verdict\": \"READY si ningún scope está bloqueado; BLOCKED si todos los scopes están bloqueados; PARTIAL_READY en otro caso.\"\n  },\n  \"schema_version\": \"A14_INPUT_HOLDOUT_V1\"\n}","request_sha256":"4526ea6f4a8dbe7cd2d131dc0f0c49c1cd8101087f8213480fe362313f36ba7b","run_id":"A14Q_C2-GPTN-PILOT-0001","schema":"ANALYSIS_GPT_NATIVE_PACKET_V1","stage_output_selector":"A14","subject_ref":"PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1/A14Q/A14Q_C2","unit":"A14"}$pkt$;
 v_m jsonb; v_before_specs jsonb; v_before_cps text; v_after_cps text; v_stored jsonb; v_id bigint; v_p jsonb;
BEGIN
 IF v_packet->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_packet->>'subject_ref' <> v_plan||'/'||v_unit||'/'||v_cp
  THEN RAISE EXCEPTION 'A14Q_C2_PACKET_IDENTITY'; END IF;
 IF encode(sha256(convert_to(v_packet#>>'{input,input_literal}','UTF8')),'hex') <> v_packet#>>'{input,input_sha256}'
  THEN RAISE EXCEPTION 'A14Q_C2_INPUT_SHA_MISMATCH'; END IF;
 IF (v_packet#>>'{limits,provider_attested}')::boolean IS NOT FALSE OR (v_packet#>>'{limits,real_execution_receipt}')::boolean IS NOT FALSE
  THEN RAISE EXCEPTION 'A14Q_C2_LIMITS_NOT_FALSE'; END IF;
 IF (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_cp) IS DISTINCT FROM 'PENDING'
  THEN RAISE EXCEPTION 'A14Q_C2_NOT_PENDING'; END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_before_cps
  FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi FOR UPDATE;
 IF v_m IS NULL THEN RAISE EXCEPTION 'A14Q_UNIT_NOT_FOUND'; END IF;
 IF v_m#>'{gpt_native_packets_v1,A14Q_C2}' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A14Q_C2,packet_sha256}' <> v_packet_sha
  THEN RAISE EXCEPTION 'A14Q_C2_PACKET_DIFFERENT_ALREADY_STORED'; END IF;
 v_before_specs := v_m->'action_specs_v1';
 UPDATE programacion.engineering_plan_units
    SET unit_metadata = v_m || jsonb_build_object('gpt_native_packets_v1',
        COALESCE(v_m->'gpt_native_packets_v1','{}'::jsonb) || jsonb_build_object('A14Q_C2',v_packet))
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 v_stored := v_m#>'{gpt_native_packets_v1,A14Q_C2}';
 IF v_stored IS DISTINCT FROM v_packet THEN RAISE EXCEPTION 'A14Q_C2_PACKET_READBACK_MISMATCH'; END IF;
 IF v_m->'action_specs_v1' IS DISTINCT FROM v_before_specs THEN RAISE EXCEPTION 'A14Q_C2_SPECS_CHANGED'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.lf_eventos WHERE evento_tipo='HANDOFF_DEEP_CONTEXT' AND created_by_execution_id=v_exec) THEN
  INSERT INTO public.lf_eventos(evento_tipo,entidad_tipo,entidad_codigo,descripcion,severidad,origen,created_by_execution_id,payload)
  VALUES('HANDOFF_DEEP_CONTEXT','PROGRAM_PLAN',v_plan||'.A14Q_C2.GPT_NATIVE_HANDOFF',
   'Frozen A14Q_C2 packet handed to GPT Native for a producer run; no acceptance declared.','INFO','DERIVE_FROM_EXECUTION_ID',v_exec,
   jsonb_build_object(
    'evidence_schema_version','operational-event/v2','execution_id',v_exec,
    'producer','ANALYSIS_QUAL_C2_GPT_HANDOFF_V1',
    'purpose','Hand the frozen A14Q_C2 packet to GPT Native so it can produce the stage output in its own chat.',
    'occurred_at',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"'),
    'acceptance_declared',false,
    'subject_ref',v_packet->>'subject_ref','checkpoint',v_cp,'work_item_id',v_wi,
    'packet_location','supabase://programacion.engineering_plan_units/'||v_unit||'#unit_metadata.gpt_native_packets_v1.'||v_cp,
    'packet_sha256',v_packet_sha,'request_sha256',v_packet->>'request_sha256',
    'input_sha256',v_packet#>>'{input,input_sha256}','producer_mode','GPT_NATIVE',
    'evidence_tier',v_packet->>'evidence_tier','provider_attested',false,
    'instructions_for_gpt',v_packet->>'prompt_for_gpt',
    'return_instructions','Reply in the same chat with ONLY the JSON object, unedited. Keep the chat link; the verifier needs the RAW JSON, the chat link and the transcript SHA-256. Do not claim provider attestation.',
    'limits_note','Owner-approved GPT Native in-chat equivalent. Not a provider receipt and not an independent review. The checkpoint stays pending until a captured output is verified.'))
  RETURNING id INTO v_id;
  SELECT payload INTO v_p FROM public.lf_eventos WHERE id=v_id;
  IF v_p->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_p->>'instructions_for_gpt' IS DISTINCT FROM v_packet->>'prompt_for_gpt'
   THEN RAISE EXCEPTION 'A14Q_C2_HANDOFF_READBACK_MISMATCH'; END IF;
 END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_after_cps
  FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 IF v_after_cps IS DISTINCT FROM v_before_cps THEN RAISE EXCEPTION 'A14Q_C2_CHECKPOINTS_CHANGED'; END IF;
END
$a14q_c2_prep$;
COMMIT;
